abhinav_23_25 = {
    'hi': '।।9.23--9.25।। श्री अभिनवगुप्त कहते हैं: श्रद्धापूर्वक अन्य देवताओं का यजन करने वाले भक्त भी अज्ञानवश मेरा ही यजन करते हैं; किंतु अविधिपूर्वक यजन करने के कारण वे मुझे तत्त्व से न जानकर देव-पित्रि-भूत लोकों को प्राप्त होते हैं, जबकि मेरे निष्काम अनन्य भक्त केवल मुझे ही प्राप्त करते हैं।',
    'en': '9.23--9.25 Sri Abhinavagupta states: Even those who worship demigods with faith worship Me alone ignorantly; failing to realize My supreme reality through improper knowledge, they go to demigods, ancestors, and spirits, whereas My exclusive devotees attain Me alone.',
    'be': '৯.২৩--৯.২৫ শ্রী অভিনবগুপ্ত বলেছেন: শ্রদ্ধাপূর্ব ক অন্য দেবতাদের যজন করা ভক্তরাও অজ্ঞানবশত আমারই যজন করে; কিন্তু অবিধিপূর্ব ক যজন করার কারণে তারা আমাকে তত্ত্ব থেকে না জেনে দেব-পিতৃ-ভূত লোক প্রাপ্ত হয়, কিন্তু আমার নিষ্কাম অনন্য ভক্তরা কেবল আমাকেই প্রাপ্ত হয়।',
    'ka': '೯.೨೩--೯.೨೫ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಶ್ರದ್ಧೆಯಿಂದ ಅನ್ಯದೇವತೆಗಳನ್ನು ಯಜನ ಮಾಡುವ ಭಕ್ತರೂ ಅಜ್ಞಾನದಿಂದ ನನ್ನನ್ನೇ ಯಜನ ಮಾಡುತ್ತಾರೆ; ಆದರೆ ಅವಿಧಿಪೂರ್ವಕವಾಗಿ ಯಜನ ಮಾಡುವ ಕಾರಣದಿಂದ ಅವರು ನನ್ನನ್ನು ತತ್ತ್ವದಿಂದ ತಿಳಿಯದೆ ದೇವ-ಪಿತೃ-ಭೂತಲೋಕಗಳನ್ನು ಪಡೆಯುತ್ತಾರೆ, ಆದರೆ ನನ್ನ ನಿಷ್ಕಾಮ ಅನನ್ಯ ಭಕ್ತರು ಕೇವಲ ನನ್ನನ್ನೇ ಪಡೆಯುತ್ತಾರೆ.'
}

abhinav_20_21 = {
    'hi': '।।9.20--9.21।। श्री अभिनवगुप्त कहते हैं: त्रिवेदी सकाम निष्पाप पुरुष सोमपान करके स्वर्ग-भोग प्राप्त करते हैं, किंतु पुण्य क्षीण होने पर पुनः मर्त्यलोक में लौटते हैं। केवल भगवान् के अनन्य निष्काम भक्त ही सर्वतोमुख परमेश्वर की नित्य प्राप्ति रूप मोक्ष प्राप्त करते हैं।',
    'en': '9.20--9.21 Sri Abhinavagupta states: Desire-driven practitioners of the three Vedas attain heavenly delights after drinking Soma, but return to the mortal world when their merits are exhausted. Only unselfish devotees of the Lord attain eternal liberation.',
    'be': '৯.২০--৯.২১ শ্রী অভিনবগুপ্ত বলেছেন: ত্রিবেদী সকাম নিষ্পাপ পুরুষরা সোমপান করে স্বর্গ-ভোগ প্রাপ্ত হয়, কিন্তু পুণ্য ক্ষীণ হলে পুনরায় মর্ত্যলোকে ফিরে আসে। কেবল ভগবানের অনন্য নিষ্কাম ভক্তরাই সর্বতোমুখ পরমেশবরের নিত্য প্রাপ্তি রূপ মোক্ষ প্রাপ্ত হয়।',
    'ka': '೯.೨೦--೯.೨೧ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ತ್ರಿವೇದಿ ಸಕಾಮ ನಿಷ್ಪಾಪ ಪುರುಷರು ಸೋಮಪಾನ ಮಾಡಿ ಸ್ವರ್ಗಭೋಗವನ್ನು ಪಡೆಯುತ್ತಾರೆ, ಆದರೆ ಪುಣ್ಯವು ಕ್ಷೀಣಿಸಿದಾಗ ಮತ್ತೆ ಮರ್ತ್ಯಲೋಕಕ್ಕೆ ಮರಳುತ್ತಾರೆ. ಕೇವಲ ಭಗವಂತನ ಅನನ್ಯ ನಿಷ್ಕಾಮ ಭಕ್ತರು ಮಾತ್ರ ಸರ್ವತೋಮುಖ ಪರಮೇಶ್ವರನ ನಿತ್ಯಪ್ರಾಪ್ತಿ ರೂಪದ ಮೋಕ್ಷವನ್ನು ಪಡೆಯುತ್ತಾರೆ.'
}

madhav_20_21 = {
    'hi': '।।9.20--9.21।। श्री मध्वाचार्य कहते हैं: सकाम यज्ञकर्त्ता इन्द्रादि देवताओं की उपासना करके स्वर्ग-भोग पाते हैं, पर पुण्य क्षीण होने पर मृत्युलोक में आते हैं। इसके विपरीत, इन्द्रादि में स्थित भगवान् की निष्काम उपासना करने वाले भक्त परम गति को प्राप्त करते हैं।',
    'en': '9.20--9.21 Sri Madhavacharya states: Performers of sacrifices seeking desires worship demigods to enjoy heavenly realms, but return to earth upon exhaustion of merit. Conversely, those who worship the Supreme Lord residing within the demigods with unselfish devotion attain supreme liberation.',
    'be': '৯.২০--৯.২১ শ্রী মধ্বাচার্য বলেছেন: সকাম যজ্ঞকর্তারা ইন্দ্রাদি দেবতাদের উপাসনা করে স্বর্গ-ভোগ পায়, কিন্তু পুণ্য ক্ষীণ হলে মৃত্যুলোকে আসে। এর বিপরীতে, ইন্দ্রাদিতে স্থিত ভগবানের নিষ্কাম উপাসনা করা ভক্তরা পরম গতি প্রাপ্ত হয়।',
    'ka': '೯.೨೦--೯.೨೧ ಶ್ರೀ ಮಧ್ವಾಚಾರ್ಯರು ಹೇಳುತ್ತಾರೆ: ಸಕಾಮ ಯಜ್ಞಕರ್ತರು ಇಂದ್ರಾದಿ ದೇವತೆಗಳನ್ನು ಉಪಾಸಿಸಿ ಸ್ವರ್ಗಭೋಗವನ್ನು ಪಡೆಯುತ್ತಾರೆ, ಆದರೆ ಪುಣ್ಯವು ಕ್ಷೀಣಿಸಿದಾಗ ಮೃತ್ಯುಲೋಕಕ್ಕೆ ಬರುತ್ತಾರೆ. ಇದಕ್ಕೆ ಪ್ರತಿಯಾಗಿ, ಇಂದ್ರಾದಿಗಳಲ್ಲಿ ಸ್ಥಿತನಾದ ಭಗವಂತನ ನಿಷ್ಕಾಮ ಉಪಾಸನೆ ಮಾಡುವ ಭಕ್ತರು ಪರಮ ಗತಿಯನ್ನು ಪಡೆಯುತ್ತಾರೆ.'
}

jaya_20_21 = {
    'hi': '।।9.20--9.21।। श्री जयतीर्थ कहते हैं: "सदसच्चाहम्" की व्याख्या करते हुए स्पष्ट करते हैं कि अन्यदेवता-याजी सकाम जन आवागमन (गतागत) के चक्र में फँसते हैं, जबकि सर्वान्तर्यामी विष्णु का निष्काम यजन करने वाले भक्त नित्य मोक्ष पाते हैं।',
    'en': '9.20--9.21 Sri Jayatirtha states: Elucidating the supreme truth, he clarifies that desire-driven worshippers of demigods remain bound to the cycle of coming and going, whereas unselfish worshippers of all-pervading Lord Vishnu attain eternal mukti.',
    'be': '৯.২০--৯.২১ শ্রী জয়তীর্থ বলেছেন: "সদসচ্চাহম্" এর ব্যাখ্যা করে স্পষ্ট করছেন যে অন্যদেবতা-যাজী সকাম জনরা গমনাগমনের (গতাগত) চক্রে আবদ্ধ হয়, কিন্তু সর্বান্তর্যামি বিষ্ণুর নিষ্কাম যজন করা ভক্তরা নিত্য মোক্ষ পায়।',
    "ka": "೯.೨೦--೯.೨೧ ಶ್ರೀ ಜಯತೀರ್ಥರು ಹೇಳುತ್ತಾರೆ: \"ಸದಸಚ್ಚಾಹಮ್\" ಎಂಬುದನ್ನು ವ್ಯಾಖ್ಯಾನಿಸುತ್ತಾ ಸ್ಪಷ್ಟಪಡಿಸುತ್ತಾರೆ: ಕಾಮ್ಯಕರ್ಮಿಗಳಾದ ಅನ್ಯದೇವತಾಯಾಜಿಗಳು ಗತಾಗತಗಳ (ಬರುವ-ಹೋಗುವ) ಚಕ್ರದಲ್ಲಿ ಸಿಲುಕುತ್ತಾರೆ, ಆದರೆ ಸರ್ವಾಂತರ್ಯಾಮಿ ವಿಷ್ಣುವಿನ ನಿಷ್ಕಾಮ ಯಜನ ಮಾಡುವ ಭಕ್ತರು ನಿತ್ಯ ಮೋಕ್ಷವನ್ನು ಪಡೆಯುತ್ತಾರೆ.",
}

vallabh_20_21 = {
    'hi': '।।9.20--9.21।। श्री वल्लभाचार्य कहते हैं: त्रिगुणमयी त्रिवेदी-मार्गगामी जन सकाम भाव से इन्द्रादि लोक भोगकर पुनः संसार में आते हैं; गतागत (जन्म-मरण) ही सकाम मार्ग का फल है, जबकि शुद्ध भगवद्भक्त सर्वथा मुक्त हो जाते हैं।',
    'en': '9.20--9.21 Sri Vallabhacharya states: Practitioners of the three Vedas with material desires enjoy celestial realms and return to earth; repeated birth and death is the fruit of desired-based rites, whereas pure devotees attain eternal freedom.',
    'be': '৯.২০--৯.২১ শ্রী বল্লভাচার্য বলেছেন: ত্রিগুণময়ী ত্রিবেদী-মার্গগামী জনরা সকাম ভাবে ইন্দ্রাদি লোক ভোগ করে পুনরায় সংসারে আসে; গতাগত (জন্ম-মরণ) ই সকাম মার্গ এর ফল, কিন্তু শুদ্ধ ভগবদ্ভক্তরা সর্বথা মুক্ত হয়ে যায়।',
    'ka': '೯.೨೦--೯.೨೧ ಶ್ರೀ ವಲ್ಲಭಾಚಾರ್ಯರು ಹೇಳುತ್ತಾರೆ: ತ್ರಿಗುಣಮಯಿ ತ್ರಿವೇದಿಮಾರ್ಗಗಾಮಿಗಳು ಸಕಾಮಭಾವದಿಂದ ಇಂದ್ರಾದಿ ಲೋಕಗಳನ್ನು ಅನುಭವಿಸಿ ಮತ್ತೆ ಸಂಸಾರಕ್ಕೆ ಬರುತ್ತಾರೆ; ಗತಾಗತಗಳೇ (ಜನ್ಮ-ಮರಣ) ಸಕಾಮಮಾರ್ಗದ ಫಲವಾಗಿದೆ, ಆದರೆ ಶುದ್ಧ ಭಗವದ್ಭಕ್ತರು ಸಂಪೂರ್ಣ ಮುಕ್ತರಾಗುತ್ತಾರೆ'
}

